package br.com.amcash.vehicle.service;

import br.com.amcash.shared.exception.*; import br.com.amcash.user.entity.*; import br.com.amcash.user.repository.UserRepository;
import br.com.amcash.vehicle.dto.request.*; import br.com.amcash.vehicle.dto.response.*; import br.com.amcash.vehicle.entity.*; import br.com.amcash.vehicle.repository.*;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
import java.io.IOException; import java.math.*; import java.time.LocalDate; import java.util.*;

@Service
public class VehicleService {
    private static final int MAX_PHOTO_BYTES=2_000_000;
    private final VehicleRepository vehicles; private final VehicleFinanceRepository finances; private final OdometerReadingRepository readings;
    private final VehicleMaintenanceRepository maintenances; private final VehiclePhotoRepository photos; private final UserRepository users; private final MaintenanceAlertService alerts;
    public VehicleService(VehicleRepository vehicles,VehicleFinanceRepository finances,OdometerReadingRepository readings,
      VehicleMaintenanceRepository maintenances,VehiclePhotoRepository photos,UserRepository users,MaintenanceAlertService alerts){this.vehicles=vehicles;this.finances=finances;this.readings=readings;this.maintenances=maintenances;this.photos=photos;this.users=users;this.alerts=alerts;}

    @Transactional(readOnly=true) public List<VehicleResponse> list(UUID userId){requireMobility(userId);return vehicles.findAllByUserIdOrderByCreatedAtDesc(userId).stream().map(v->response(v,false)).toList();}
    @Transactional(readOnly=true) public VehicleResponse get(UUID userId,UUID id){requireMobility(userId);return response(find(userId,id),true);}
    @Transactional public VehicleResponse create(UUID userId,VehicleRequest request){User user=requireMobility(userId);validate(request);Vehicle v=new Vehicle(user);apply(v,request);vehicles.save(v);saveFinance(v,request);readings.save(new OdometerReading(v,request.currentMileage(),request.mileageReadingDate(),false));return response(v,true);}
    @Transactional public VehicleResponse update(UUID userId,UUID id,VehicleRequest request){requireMobility(userId);validate(request);Vehicle v=find(userId,id);boolean odometerChanged=v.getCurrentMileage().compareTo(request.currentMileage())!=0||!v.getMileageReadingDate().equals(request.mileageReadingDate());apply(v,request);saveFinance(v,request);if(odometerChanged)readings.save(new OdometerReading(v,request.currentMileage(),request.mileageReadingDate(),true));alerts.reconcile(v);return response(v,true);}
    @Transactional public OdometerReadingResponse updateOdometer(UUID userId,UUID id,OdometerRequest request){requireMobility(userId);Vehicle v=find(userId,id);v.updateOdometer(request.mileage(),request.readingDate());OdometerReading saved=readings.save(new OdometerReading(v,request.mileage(),request.readingDate(),request.correction()));alerts.reconcile(v);return reading(saved);}
    @Transactional public MaintenanceResponse addMaintenance(UUID userId,UUID vehicleId,MaintenanceRequest request){requireMobility(userId);Vehicle v=find(userId,vehicleId);validate(request);VehicleMaintenance item=new VehicleMaintenance(v);apply(item,request);maintenances.save(item);alerts.resolveCompleted(item);alerts.reconcile(v);return maintenance(item);}
    @Transactional public MaintenanceResponse updateMaintenance(UUID userId,UUID vehicleId,UUID maintenanceId,MaintenanceRequest request){requireMobility(userId);Vehicle v=find(userId,vehicleId);VehicleMaintenance item=maintenances.findByIdAndVehicleUserId(maintenanceId,userId).filter(m->m.getVehicle().getId().equals(vehicleId)).orElseThrow(()->new NotFoundException("Manutenção não encontrada"));validate(request);apply(item,request);alerts.reconcile(v);return maintenance(item);}
    @Transactional public void deleteMaintenance(UUID userId,UUID vehicleId,UUID maintenanceId){requireMobility(userId);Vehicle v=find(userId,vehicleId);VehicleMaintenance item=maintenances.findByIdAndVehicleUserId(maintenanceId,userId).filter(m->m.getVehicle().getId().equals(vehicleId)).orElseThrow(()->new NotFoundException("Manutenção não encontrada"));maintenances.delete(item);maintenances.flush();alerts.reconcile(v);}
    @Transactional public void savePhoto(UUID userId,UUID vehicleId,MultipartFile file){requireMobility(userId);Vehicle v=find(userId,vehicleId);String type=file.getContentType();if(file.isEmpty()||file.getSize()>MAX_PHOTO_BYTES||!("image/jpeg".equals(type)||"image/webp".equals(type)))throw new BadRequestException("Envie uma imagem JPEG ou WebP de até 2 MB");try{byte[] content=file.getBytes();if(!validImageSignature(type,content))throw new BadRequestException("O conteúdo da foto não corresponde ao formato informado");VehiclePhoto photo=photos.findById(vehicleId).orElseGet(()->new VehiclePhoto(v));photo.update(type,content);photos.save(photo);}catch(IOException ex){throw new BadRequestException("Não foi possível processar a foto");}}
    @Transactional public void deletePhoto(UUID userId,UUID vehicleId){requireMobility(userId);find(userId,vehicleId);photos.deleteById(vehicleId);}
    @Transactional(readOnly=true) public PhotoData photo(UUID userId,UUID vehicleId){requireMobility(userId);find(userId,vehicleId);VehiclePhoto photo=photos.findById(vehicleId).orElseThrow(()->new NotFoundException("Foto não encontrada"));return new PhotoData(photo.getContentType(),photo.getContent());}

    private void apply(Vehicle v,VehicleRequest r){v.update(r.type(),clean(r.brand()),clean(r.model()),r.manufactureYear(),r.modelYear(),cleanNullable(r.version()),cleanNullable(r.nickname()),upperNullable(r.licensePlate()),r.fuelType(),r.currentMileage(),r.mileageReadingDate(),r.gasolineConsumption(),r.ethanolConsumption(),r.electricConsumption(),r.acquisitionDate());}
    private void saveFinance(Vehicle v,VehicleRequest r){VehicleFinance f=finances.findById(v.getId()).orElseGet(()->new VehicleFinance(v));f.update(r.financialStatus(),r.financialStatus()==FinancialStatus.PAID_OFF?null:r.monthlyAmount(),r.financialStatus()==FinancialStatus.FINANCED?r.totalInstallments():null,r.financialStatus()==FinancialStatus.FINANCED?r.paidInstallments():null,r.financialStatus()==FinancialStatus.FINANCED?r.nextDueDate():null);finances.save(f);}
    private void apply(VehicleMaintenance m,MaintenanceRequest r){m.update(r.type(),cleanNullable(r.customName()),r.date(),r.mileage(),r.amount(),cleanNullable(r.description()),r.nextMileage(),r.nextDate());}
    private void validate(VehicleRequest r){
        if(r.modelYear()<r.manufactureYear()||r.modelYear()>r.manufactureYear()+1)throw new BadRequestException("Ano do modelo deve ser igual ou posterior ao de fabricação");
        if(r.financialStatus()==FinancialStatus.FINANCED&&(r.monthlyAmount()==null||r.totalInstallments()==null||r.paidInstallments()==null||r.nextDueDate()==null))throw new BadRequestException("Informe os dados do financiamento");
        if(r.financialStatus()==FinancialStatus.FINANCED&&r.paidInstallments()>r.totalInstallments())throw new BadRequestException("Parcelas pagas não podem superar o total");
        if(r.financialStatus()==FinancialStatus.RENTED&&r.monthlyAmount()==null)throw new BadRequestException("Informe o valor mensal do aluguel");
        if(r.fuelType()==FuelType.FLEX&&(r.gasolineConsumption()==null&&r.ethanolConsumption()==null))throw new BadRequestException("Informe ao menos um consumo médio do veículo flex");
    }
    private void validate(MaintenanceRequest r){if(r.type()==MaintenanceType.OTHER&&(r.customName()==null||r.customName().isBlank()))throw new BadRequestException("Informe o nome da manutenção");if(r.nextMileage()!=null&&r.nextMileage().compareTo(r.mileage())<=0)throw new BadRequestException("A próxima quilometragem deve ser maior que a atual");if(r.nextDate()!=null&&r.nextDate().isBefore(r.date()))throw new BadRequestException("A próxima data não pode ser anterior à manutenção");}
    private User requireMobility(UUID id){User u=users.findById(id).orElseThrow(()->new NotFoundException("Usuário não encontrado"));if(u.getUsageProfile()==null||u.getUsageProfile()==UsageProfile.PERSONAL)throw new ForbiddenException("Veículos está disponível apenas no perfil Mobilidade");return u;}
    private Vehicle find(UUID userId,UUID id){return vehicles.findByIdAndUserId(id,userId).orElseThrow(()->new NotFoundException("Veículo não encontrado"));}
    private VehicleResponse response(Vehicle v,boolean detail){VehicleFinance f=finances.findById(v.getId()).orElseThrow();List<OdometerReadingResponse> rs=detail?readings.findAllByVehicleIdOrderByReadingDateDescCreatedAtDesc(v.getId()).stream().map(this::reading).toList():List.of();List<MaintenanceResponse> ms=detail?maintenances.findAllByVehicleIdOrderByDateDescCreatedAtDesc(v.getId()).stream().map(this::maintenance).toList():List.of();return new VehicleResponse(v.getId(),v.getType(),v.getBrand(),v.getModel(),v.getManufactureYear(),v.getModelYear(),v.getVersion(),v.getNickname(),v.getLicensePlate(),v.getFuelType(),v.getCurrentMileage(),v.getMileageReadingDate(),v.getGasolineConsumption(),v.getEthanolConsumption(),v.getElectricConsumption(),v.getAcquisitionDate(),photos.existsById(v.getId()),finance(f),rs,ms);}
    private VehicleFinanceResponse finance(VehicleFinance f){Integer remaining=f.getTotalInstallments()==null?null:Math.max(0,f.getTotalInstallments()-f.getPaidInstallments());BigDecimal projected=remaining==null||f.getMonthlyAmount()==null?null:f.getMonthlyAmount().multiply(BigDecimal.valueOf(remaining)).setScale(2,RoundingMode.HALF_UP);LocalDate end=remaining==null||remaining==0||f.getNextDueDate()==null?null:f.getNextDueDate().plusMonths(remaining-1L);return new VehicleFinanceResponse(f.getStatus(),f.getMonthlyAmount(),f.getTotalInstallments(),f.getPaidInstallments(),f.getNextDueDate(),remaining,projected,end);}
    private OdometerReadingResponse reading(OdometerReading r){return new OdometerReadingResponse(r.getId(),r.getMileage(),r.getReadingDate(),r.isCorrection());}
    private MaintenanceResponse maintenance(VehicleMaintenance m){return new MaintenanceResponse(m.getId(),m.getType(),m.getCustomName(),m.getDate(),m.getMileage(),m.getAmount(),m.getDescription(),m.getNextMileage(),m.getNextDate());}
    private String clean(String s){return s.trim();} private String cleanNullable(String s){return s==null||s.isBlank()?null:s.trim();} private String upperNullable(String s){String c=cleanNullable(s);return c==null?null:c.toUpperCase(Locale.ROOT);}
    private boolean validImageSignature(String type,byte[] bytes){if("image/jpeg".equals(type))return bytes.length>3&&(bytes[0]&255)==0xff&&(bytes[1]&255)==0xd8&&(bytes[2]&255)==0xff;return bytes.length>12&&bytes[0]=='R'&&bytes[1]=='I'&&bytes[2]=='F'&&bytes[3]=='F'&&bytes[8]=='W'&&bytes[9]=='E'&&bytes[10]=='B'&&bytes[11]=='P';}
    public record PhotoData(String contentType,byte[] content){}
}
